Lemma w4s34_pre : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
         (x1 gp tp x5 x6 x7 x8 x10 x11 x12 x13 x14 x15 x17 x18 x19 x20 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
         (P PE PP B tl mtl : Z) (w256 : word),
    rw_cells asegs mm (P + 248) [C4 (Z_to_bv 64 B)] ->
    rw_cells asegs mm (P + 256) [C8 w256] ->
    mem_inv asegs mm ->
    rng RNG P 496 ->
    rng_aimg RNG ->
    0x10007fff8000 <= P ->
    P + 496 <= 2^47 ->
    0 <= PP <= PE ->
    PE < 2^47 ->
    0 <= B < 2^31 ->
    1 <= tl <= 12 ->
    1 <= mtl <= 12 ->
    (PE - PP < 4 -> forall (y11 y14 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 (Z_to_bv 64 PE) x10 y11 x12 x13 y14 (Z_to_bv 64 B)
