           (Z_to_bv 64 0x92c60) fc None mm (seg_rom asegs))) ->
    (4 <= PE - PP -> 64 < B -> forall (mm' : amem) (w : word) (y11 y14 y17 : word),
       munch [(P + 256, P + 264)] mm mm' ->
       wmono asegs mm mm' ->
       mem_inv asegs mm' ->
       rw_cells asegs mm' (P + 248) [C4 (Z_to_bv 64 B)] ->
       rw_cells asegs mm' (P + 256) [C8 w] ->
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 x8 (Z_to_bv 64 PE) x10 y11 x12 x13 y14 (Z_to_bv 64 B)
           (Z_to_bv 64 PP) y17 x18 x19 x20 (Z_to_bv 64 (tl + 256 * mtl)) x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) F
           (Z_to_bv 64 0x92d7c) fc None mm' (seg_rom asegs))) ->
    (4 <= PE - PP -> B <= 64 -> forall (y14 : word),
       evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (64 - tl)) x6 x7 x8 (Z_to_bv 64 PE) x10 (Z_to_bv 64 PP)
           x12 x13 y14 (Z_to_bv 64 B) (Z_to_bv 64 PP) (Z_to_bv 64 64) x18 x19 x20 (Z_to_bv 64 (tl + 256 * mtl)) x22
           x23 x24 x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 0x9292c) fc None mm (seg_rom asegs))) ->
